// ─── File: src/main/java/com/bank/cleanup/service/DataCleanupService.java ───
package com.bank.cleanup.service;

import com.bank.cleanup.dto.CleanupReport;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.function.Predicate;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

@Service
@Slf4j
public class DataCleanupService {

    // Compiled regex patterns (thread-safe, reusable)
    private static final Pattern IFSC_PATTERN = Pattern.compile("[A-Z]{4}0[A-Z0-9]{6}");
    private static final Pattern PAN_PATTERN = Pattern.compile("[A-Z]{5}[0-9]{4}[A-Z]");
    private static final Pattern ACCOUNT_PATTERN = Pattern.compile("\\d{9,18}");

    public CleanupReport cleanData() {
        List<String> improvements = new ArrayList<>();

        // ═══ 1. Predicate.not(String::isBlank) — clean negation ═══
        List<String> rawNames = Arrays.asList("Rajesh Kumar", "", "  ", "Priya Sharma",
            null, "Amit Patel", " ");

        List<String> nonBlankNames = rawNames.stream()
            .filter(Objects::nonNull)                       // remove nulls
            .filter(Predicate.not(String::isBlank))         // NOT blank (Java 11)
            .map(String::strip)                              // trim whitespace
            .toList();
        // ["Rajesh Kumar", "Priya Sharma", "Amit Patel"]
        improvements.add("Predicate.not(String::isBlank) replaces s -> !s.isBlank()");

        // ═══ 2. Pattern.asMatchPredicate() — ENTIRE string must match ═══
        List<String> ifscInputs = List.of("SBIN0001234", "HDFC0002345", "INVALID",
            "sbin0001234", "ICIC0ABCDEF", "TOO_LONG_IFSC_CODE");

        List<String> validIfsc = ifscInputs.stream()
            .filter(IFSC_PATTERN.asMatchPredicate())    // entire string must match IFSC regex
            .toList();
        // ["SBIN0001234", "HDFC0002345", "ICIC0ABCDEF"]
        improvements.add("Pattern.asMatchPredicate() — entire string must match (uses matches())");

        // ═══ 3. Pattern.asPredicate() — string CONTAINS a match ═══
        List<String> narrations = List.of(
            "NEFT to SBIN0001234 for rent",
            "UPI payment to grocery store",
            "RTGS to HDFC0002345 urgent",
            "ATM withdrawal 5000");

        List<String> narrationWithIfsc = narrations.stream()
            .filter(IFSC_PATTERN.asPredicate())          // string CONTAINS IFSC pattern
            .toList();
        // ["NEFT to SBIN0001234 for rent", "RTGS to HDFC0002345 urgent"]
        improvements.add("Pattern.asPredicate() — string contains match (uses find())");

        // ═══ 4. PAN validation with asMatchPredicate ═══
        List<String> panInputs = List.of("ABCDE1234F", "abcde1234f", "12345", "XYZPQ9876R");

        List<String> validPans = panInputs.stream()
            .filter(PAN_PATTERN.asMatchPredicate())
            .toList();
        // ["ABCDE1234F", "XYZPQ9876R"]

        // ═══ 5. COMBINED pipeline — clean customer records ═══
        List<String> rawRecords = Arrays.asList(
            "Rajesh Kumar|SBIN0001234|ABCDE1234F",
            "  |INVALID|12345",
            "Priya Sharma|HDFC0002345|XYZPQ9876R",
            null,
            "|SBIN0009999|VALID1234X");

        List<String> cleanedRecords = rawRecords.stream()
            .filter(Objects::nonNull)
            .filter(Predicate.not(String::isBlank))
            .filter(record -> {
                String[] parts = record.split("\\|");
                return parts.length == 3
                    && !parts[0].isBlank()
                    && IFSC_PATTERN.asMatchPredicate().test(parts[1])
                    && PAN_PATTERN.asMatchPredicate().test(parts[2]);
            })
            .toList();
        // ["Rajesh Kumar|SBIN0001234|ABCDE1234F", "Priya Sharma|HDFC0002345|XYZPQ9876R"]

        return new CleanupReport(nonBlankNames, validIfsc, validPans,
            narrationWithIfsc, cleanedRecords, improvements);
    }
}
