// ─── File: src/test/java/com/bank/cleanup/service/PredicateUtilsTest.java ───
package com.bank.cleanup.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.function.Predicate;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class PredicateUtilsTest {

    // ═══ Predicate.not() ═══
    @Test
    void predicateNotCleansNegation() {
        List<String> result = List.of("A", "", "B", "  ", "C").stream()
            .filter(Predicate.not(String::isBlank))
            .toList();
        assertThat(result).containsExactly("A", "B", "C");
    }

    @Test
    void predicateNotWithMethodRef() {
        List<List<String>> lists = List.of(List.of("A"), List.of(), List.of("B", "C"));
        List<List<String>> nonEmpty = lists.stream()
            .filter(Predicate.not(List::isEmpty))
            .toList();
        assertThat(nonEmpty).hasSize(2);
    }

    // ═══ Pattern.asMatchPredicate() — entire string ═══
    @Test
    void asMatchPredicateFullMatch() {
        Pattern ifsc = Pattern.compile("[A-Z]{4}0[A-Z0-9]{6}");

        assertThat(ifsc.asMatchPredicate().test("SBIN0001234")).isTrue();      // full match ✅
        assertThat(ifsc.asMatchPredicate().test("X SBIN0001234 Y")).isFalse(); // extra text ❌
        assertThat(ifsc.asMatchPredicate().test("sbin0001234")).isFalse();     // lowercase ❌
    }

    // ═══ Pattern.asPredicate() — contains ═══
    @Test
    void asPredicateContainsMatch() {
        Pattern ifsc = Pattern.compile("[A-Z]{4}0[A-Z0-9]{6}");

        assertThat(ifsc.asPredicate().test("SBIN0001234")).isTrue();            // full match ✅
        assertThat(ifsc.asPredicate().test("Pay to SBIN0001234 now")).isTrue(); // CONTAINS ✅
        assertThat(ifsc.asPredicate().test("no match here")).isFalse();         // no match ❌
    }

    // ═══ Difference between asPredicate and asMatchPredicate ═══
    @Test
    void differenceAsPredicateVsAsMatchPredicate() {
        Pattern pattern = Pattern.compile("\\d{3}");

        // asPredicate: find() — looks for pattern ANYWHERE in string
        assertThat(pattern.asPredicate().test("abc123def")).isTrue();   // contains "123" ✅

        // asMatchPredicate: matches() — ENTIRE string must match
        assertThat(pattern.asMatchPredicate().test("abc123def")).isFalse(); // extra chars ❌
        assertThat(pattern.asMatchPredicate().test("123")).isTrue();       // exact match ✅
    }

    // ═══ In stream filter ═══
    @Test
    void patternPredicateInStreamFilter() {
        Pattern pan = Pattern.compile("[A-Z]{5}[0-9]{4}[A-Z]");
        List<String> valid = List.of("ABCDE1234F", "invalid", "XYZPQ9876R").stream()
            .filter(pan.asMatchPredicate())
            .toList();
        assertThat(valid).containsExactly("ABCDE1234F", "XYZPQ9876R");
    }

    // ═══ Combined: not + pattern ═══
    @Test
    void combinedNotAndPattern() {
        Pattern digits = Pattern.compile("\\d+");
        List<String> nonNumeric = List.of("RELIANCE", "123", "TCS", "456", "HDFC").stream()
            .filter(Predicate.not(digits.asMatchPredicate()))  // NOT all-digits
            .toList();
        assertThat(nonNumeric).containsExactly("RELIANCE", "TCS", "HDFC");
    }
}
